package palindrome

import (
	"fmt"
	"strconv"
)

// Product holds a palindromic product and all of its factorizations
// within the given range.
type Product struct {
	Product      int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of
// two numbers in the range [fmin, fmax], along with all factor pairs
// within the range for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax")
	}

	min, max := Product{}, Product{}
	haveMin, haveMax := false, false

	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ {
			p := a * b
			if !isPalindrome(p) {
				continue
			}
			if !haveMin || p < min.Product {
				min = Product{Product: p, Factorizations: [][2]int{{a, b}}}
				haveMin = true
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{a, b})
			}
			if !haveMax || p > max.Product {
				max = Product{Product: p, Factorizations: [][2]int{{a, b}}}
				haveMax = true
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{a, b})
			}
		}
	}

	if !haveMin {
		return Product{}, Product{}, fmt.Errorf("no palindromes found")
	}
	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

